<?php
namespace App\Http\Controllers;
use App\Models\GalleryImage; use App\Services\FileCompressionService; use Illuminate\Http\Request; use Illuminate\Support\Facades\Storage;
class GalleryController extends Controller {public function index(){return response()->json(GalleryImage::where('status','approved')->latest()->limit(100)->get()->map(fn(GalleryImage $g)=>['id'=>$g->id,'category'=>$g->category,'caption'=>$g->caption,'image_url'=>route('gallery.show',$g)]));}public function store(Request $r,FileCompressionService $images){$max=config('gpcs_uploads.gallery_max_mb',20)*1024;$v=$r->validate(['image'=>['required','image','max:'.$max],'category'=>'required|string|max:100','caption'=>'nullable|string|max:255']);$f=$r->file('image');$path=$f->store('gallery','public');$abs=storage_path('app/public/'.$path);$images->compressImageInPlace($abs);$image=GalleryImage::create(['user_id'=>$r->user()->id,'category'=>$v['category'],'caption'=>$v['caption']??null,'file_path'=>$path,'original_name'=>$f->getClientOriginalName(),'mime_type'=>$f->getMimeType(),'file_size'=>filesize($abs)?:$f->getSize(),'status'=>'pending']);return response()->json(['message'=>'Image uploaded for Admin review.','id'=>$image->id],201);}public function show(GalleryImage $image){abort_unless($image->status==='approved',404);abort_unless(Storage::disk('public')->exists($image->file_path),404);return Storage::disk('public')->response($image->file_path);}}
